questionvariables.text:
/* River pollution: mixed measurement units */

n: 20;

/* Pearson correlation */
pearson_calc(A,B):=block(
    [m:length(A),ma,mb,sa,sb,sab],
    ma:sum(A[k],k,1,m)/m,
    mb:sum(B[k],k,1,m)/m,
    sa:sum((A[k]-ma)^2,k,1,m),
    sb:sum((B[k]-mb)^2,k,1,m),
    sab:sum((A[k]-ma)*(B[k]-mb),k,1,m),
    float(sab/sqrt(sa*sb))
);

/* Irregular sampling distances, to one decimal place */
distances: makelist(
    float(2*k+(rand(15)-7)/10),
    k,1,n
);

/* Generate concentrations with a negative trend */
base_conc: 12+rand(5);
decline: (15+rand(11))/100;

/* Random measurement variation */
noise: makelist(
    (rand(401)-200)/100,
    k,1,n
);

clean_conc: makelist(
    float(
        round(
            100*(base_conc-decline*k+noise[k])
        )/100
    ),
    k,1,n
);

/* Trial correlations */
r_clean: pearson_calc(
    distances,
    clean_conc
);

/* Retain a moderately scattered negative relationship */
while not (
    r_clean >= -0.90
    and r_clean <= -0.80
) do (
    noise: makelist(
        (rand(401)-200)/100,
        k,1,n
    ),

    clean_conc: makelist(
        float(
            round(
                100*(base_conc-decline*k+noise[k])
            )/100
        ),
        k,1,n
    ),

    r_clean: pearson_calc(
        distances,
        clean_conc
    )
);

/* First ten samples in mg/L;
   last ten samples in micrograms/L */
recorded_conc: makelist(
    if k<=10
    then clean_conc[k]
    else 1000*clean_conc[k],
    k,1,n
);

units: makelist(
    if k<=10
    then "mg/L"
    else "ug/L",
    k,1,n
);

/* Site identifiers */
sites: makelist(
    sconcat("S",k),
    k,1,n
);

/* Downloadable CSV */
lab: [
    "Site",
    "Distance_downstream_km",
    "Recorded_concentration",
    "Unit"
];

data: makelist(
    [
        sites[k],
        distances[k],
        recorded_conc[k],
        units[k]
    ],
    k,1,n
);

/* Correlation before unit conversion */
r_raw: pearson_calc(
    distances,
    recorded_conc
);

/* Three-decimal answers */
r_raw_display:
    float(round(1000*r_raw)/1000);

r_clean_display:
    float(round(1000*r_clean)/1000);

/* Dropdown */
options_final: [
    [0,false,"No relationship"],
    [1,false,"Weak positive linear relationship"],
    [2,false,"Weak negative linear relationship"],
    [3,false,"Strong positive linear relationship"],
    [4,true,"Strong negative linear relationship"],
    [5,false,"None of the above"]
];

ta_raw: 3;
ta_clean: 4;

feedbackvariables.text:
/* ECF classification of the student's coefficient */
ecf_r: float(ans1);
ecf_class: if ecf_r < -1 or ecf_r > 1 then -1 elseif ecf_r <= -0.6 then 4 elseif ecf_r <= -0.1 then 2 elseif ecf_r >= 0.6 then 3 elseif ecf_r >= 0.1 then 1 else -1;
options_final: [ [0,false,"No relationship"], [1,false,"Weak positive linear relationship"], [2,false,"Weak negative linear relationship"], [3,false,"Strong positive linear relationship"], [4,true,"Strong negative linear relationship"], [5,false,"None of the above"] ];
